# @spec docs/BACKLOG.md#sls-070 | docs/CODE_EDITOR_ARCHIVE_LIMITS.md#réalisation-du-passage-de-frontières
# @verifies docs/BACKLOG.md#sls-070 | docs/CODE_EDITOR_ARCHIVE_LIMITS.md#frontières-du-paquet
"""Original data ZIPs, generated by the control image's standard zipfile only."""
import base64,hashlib,json,os,stat,sys,zipfile,zlib
from pathlib import Path

BLOCK=65536;MAX_ZIP=64*1024**2;MAX_TOTAL=256*1024**2;MODE=0o444
OUT=Path(sys.argv[1]);assert str(OUT)=='/output' and OUT.is_dir()
HANDLER=Path('/fixture-source/editor-archive-limits.cjs').read_bytes()
B=b'B'+base64.b64encode(hashlib.shake_256(b'editor archive marker original').digest(768))[1:]
A=b'A'+B[1:];assert len(A)==len(B)==1024 and A!=B

def sha_file(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  while data:=f.read(BLOCK):h.update(data)
 return h.hexdigest()

def raw(value):return value.read_bytes() if isinstance(value,Path) else value

def size(value):return value.stat().st_size if isinstance(value,Path) else len(value)

def inventory(files):
 return {name:{'size':size(value),'sha256':sha_file(value) if isinstance(value,Path) else hashlib.sha256(value).hexdigest(),'mode':MODE} for name,value in sorted(files.items())}

def fingerprint(value):return hashlib.sha256(json.dumps(value,sort_keys=True).encode()).hexdigest()

def parents(files):
 return {'/'.join(name.split('/')[:i]) for name in files for i in range(1,len(name.split('/')))}

def archive(target,files,method,modified_marker=False):
 with zipfile.ZipFile(target,'w',compression=method,compresslevel=6 if method==zipfile.ZIP_DEFLATED else None,allowZip64=False) as z:
  for name,value in sorted(files.items()):
   info=zipfile.ZipInfo(name,(1980,1,1,0,0,0));info.create_system=3;info.compress_type=method;info.external_attr=(stat.S_IFREG|MODE)<<16;info.file_size=size(value)
   with z.open(info,'w',force_zip64=False) as f:
    if isinstance(value,Path):
     with value.open('rb') as source:
      while data:=source.read(BLOCK):f.write(data)
    elif modified_marker and name=='marker.txt':f.write(value)
    else:
     for offset in range(0,len(value),BLOCK):f.write(value[offset:offset+BLOCK])
 return target.stat().st_size

def resize_random(p,length):
 assert 0<length<=MAX_ZIP
 before=p.stat().st_size if p.exists() else 0
 with p.open('r+b' if p.exists() else 'w+b') as f:
  if before>=length:f.truncate(length)
  else:
   f.seek(before);position=before
   while position<length:
    chunk=hashlib.shake_256(b'editor archive binary original'+(position//BLOCK).to_bytes(8,'big')).digest(BLOCK)
    piece=chunk[position%BLOCK:min(BLOCK,position%BLOCK+length-position)];f.write(piece);position+=len(piece)
 p.chmod(0o600)

def compressed(data):
 c=zlib.compressobj(zlib.Z_DEFAULT_COMPRESSION,zlib.DEFLATED,-15)
 return len(c.compress(data)+c.flush())

def summarize(files,inv):
 return {'files':len(files),'directories':len(parents(files)),'bytes':sum(v['size'] for v in inv.values()),'inventory_sha256':fingerprint(inv),'marker_bytes':len(files['marker.txt']),'marker_sha256':hashlib.sha256(files['marker.txt']).hexdigest(),'payloads':[{'path':n,'bytes':v['size'],'sha256':v['sha256']} for n,v in inv.items() if n.startswith('payload') and '/' not in n]}

cases={};base={'editor-archive-limits.cjs':HANDLER,'marker.txt':A}
for kind in ['compressed','expanded','files','directories','recovery']:
 folder=OUT/kind;folder.mkdir(mode=0o700);files=dict(base);adjustments=[]
 if kind=='compressed':
  payload=folder/'payload.bin';length=MAX_ZIP-BLOCK
  for attempt in range(16):
   resize_random(payload,length);files['payload.bin']=payload;candidate=files|{'marker.txt':B}
   observed=archive(folder/'predicted.zip',candidate,zipfile.ZIP_DEFLATED,True);adjustments.append({'payload_bytes':length,'zip_bytes':observed})
   if observed==MAX_ZIP:break
   length+=MAX_ZIP-observed
  else:raise RuntimeError('exact_zip_calibration_failed')
  overflow=next((B+bytes([v]) for v in range(33,127) if compressed(B+bytes([v]))==compressed(B)+1),None)
  assert overflow is not None
 elif kind=='expanded':
  remaining=MAX_TOTAL-len(HANDLER)-len(A)
  for i in range(4):
   n=min(MAX_ZIP,remaining);p=folder/('payload-'+str(i)+'.bin')
   with p.open('wb') as f:f.truncate(n)
   p.chmod(0o600);files[p.name]=p;remaining-=n
  assert remaining==0;overflow=B+b'x'
 elif kind=='files':
  files.update({f'item-{i:05d}.bin':b'' for i in range(20000-len(files))});overflow=B+b'x'
 elif kind=='directories':
  files.update({f'd{i:05d}/e/f.bin':b'' for i in range(10000)});overflow=B+b'x'
 else:files['payload.bin']=b'Archive recovery';overflow=B+b'x'
 a=inventory(files);bfiles=files|{'marker.txt':B};bi=inventory(bfiles)
 predicted_bytes=archive(folder/'predicted.zip',bfiles,zipfile.ZIP_DEFLATED,True)
 input_bytes=archive(folder/'input.zip',files,zipfile.ZIP_STORED if kind=='compressed' else zipfile.ZIP_DEFLATED)
 assert input_bytes<MAX_ZIP and predicted_bytes<=MAX_ZIP
 if kind=='compressed':assert predicted_bytes==MAX_ZIP and compressed(overflow)-compressed(B)==1
 if kind=='expanded':assert sum(v['size'] for v in bi.values())==MAX_TOTAL
 if kind=='files':assert len(bi)==20000 and len(parents(bfiles))==0
 if kind=='directories':assert len(parents(bfiles))==20000 and len(bi)==10002
 for name,value in [('inventory-a.json',a),('inventory-b.json',bi)]:
  (folder/name).write_text(json.dumps(value,sort_keys=True)+'\n');(folder/name).chmod(0o600)
 (folder/'marker-b.txt').write_bytes(B);(folder/'marker-overflow.txt').write_bytes(overflow)
 for p in folder.iterdir():p.chmod(0o600)
 cases[kind]={'input_zip':'input.zip','input_bytes':input_bytes,'input_sha256':sha_file(folder/'input.zip'),'predicted_zip_bytes':predicted_bytes,'predicted_zip_sha256':sha_file(folder/'predicted.zip'),'a':summarize(files,a),'b':summarize(bfiles,bi),'overflow_marker_bytes':len(overflow),'overflow_marker_sha256':hashlib.sha256(overflow).hexdigest(),'calibration':adjustments}
value={'completed':True,'python':sys.version,'zipfile_sha256':sha_file(Path(zipfile.__file__)),'zlib_version':zlib.ZLIB_VERSION,'zlib_runtime_version':zlib.ZLIB_RUNTIME_VERSION,'zlib_module_sha256':sha_file(Path(zlib.__file__)),'cases':cases}
p=OUT/'metadata.json';p.write_text(json.dumps(value,sort_keys=True,indent=2)+'\n');p.chmod(0o600)
print(json.dumps({'completed':True,'metadata_sha256':sha_file(p),'cases':len(cases)}))
